{
  "avaliacoes": [
    {
      "id": "E12333b34110546fe",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "KPIs são métricas ou indicadores de desempenho usados para avaliar a eficiência de processos industriais, podendo comparar resultados reais com teóricos e cobrir cronograma, ciclo, consumo de energia e matérias-primas, além de aspectos de controle, operação e manutenção.",
          "trechos": [
            "E12333b34110546fe:0:694",
            "E12333b34110546fe:694:1392"
          ],
          "condicoes": [
            "aplicação no contexto de processos industriais e gestão de plantas de produção",
            "a escolha da forma de expressão depende do interesse da avaliação"
          ],
          "limites": [
            "o trecho caracteriza usos possíveis, mas não fixa um denominador único para cada KPI",
            "não apresenta metas numéricas nem critérios formais de qualidade de dados"
          ]
        },
        {
          "proposicao": "Os indicadores são apresentados como instrumentos para identificar deficiências e apoiar melhora de desempenho, com possível redução de custos e aumento de capacidade sem grandes investimentos.",
          "trechos": [
            "E12333b34110546fe:694:1392"
          ],
          "condicoes": [
            "o uso está associado à identificação de deficiências no processo",
            "podem ser aplicados a equipamentos, etapas do processo ou à planta como um todo"
          ],
          "limites": [
            "o texto descreve objetivo e potencial esperado, não comprovação universal de resultado",
            "não informa método de cálculo para ligar indicador à decisão operacional"
          ]
        },
        {
          "proposicao": "A definição da métrica depende do uso e do usuário, e o uso mais atual descrito no trecho é a aplicação em tempo real em painéis de controle.",
          "trechos": [
            "E12333b34110546fe:1392:2092",
            "E12333b34110546fe:2092:2299"
          ],
          "condicoes": [
            "adoção em contexto de gerenciamento de desempenho e gestão de plantas",
            "seleção da métrica conforme finalidade de uso e público usuário"
          ],
          "limites": [
            "o trecho não estabelece requisitos mínimos de atualização, frequência ou governança dos dados",
            "a menção a painéis em tempo real é descritiva, não normativa"
          ]
        }
      ]
    },
    {
      "id": "Ecd5ae3758cce18ae",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Indicador ambiental é descrito como expressão específica que fornece informações sobre o desempenho ambiental da organização, e a classificação mencionada agrupa indicadores em desempenho ambiental e condições ambientais.",
          "trechos": [
            "Ecd5ae3758cce18ae:0:698",
            "Ecd5ae3758cce18ae:698:1394"
          ],
          "condicoes": [
            "uso no processo de medição de desempenho ambiental",
            "referência a classificação associada a normas ISO com números suprimidos"
          ],
          "limites": [
            "os identificadores das normas estão apagados e não podem ser reconstruídos",
            "o trecho não detalha fórmulas, denominadores ou metas para os indicadores"
          ]
        },
        {
          "proposicao": "Os indicadores de desempenho ambiental são subdivididos em indicadores de desempenho da gestão e indicadores de desempenho operacional, enquanto os indicadores de condições ambientais descrevem o estado do ambiente em diferentes escalas.",
          "trechos": [
            "Ecd5ae3758cce18ae:0:698",
            "Ecd5ae3758cce18ae:698:1394"
          ],
          "condicoes": [
            "classificação apresentada no âmbito da medição de desempenho ambiental"
          ],
          "limites": [
            "o trecho não define critérios de seleção entre MPI, OPI e ECI para um caso específico de FPSO",
            "não há orientação explícita sobre qualidade de dados ou frequência de monitoramento"
          ]
        },
        {
          "proposicao": "A associação entre maturidade ambiental da organização e escolha de indicadores é apresentada como incorporação de indicadores apropriados aos estágios evolutivos da empresa, desde foco reativo em cumprimento legal até fase proativa com programas voluntários.",
          "trechos": [
            "Ecd5ae3758cce18ae:698:1394"
          ],
          "condicoes": [
            "a adequação dos indicadores varia conforme o estágio evolutivo da organização"
          ],
          "limites": [
            "a passagem descreve uma associação conceitual, não um critério obrigatório universal",
            "não especifica como medir maturidade ambiental nem como convertê-la em metas"
          ]
        }
      ]
    },
    {
      "id": "E9a375624755afb26",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Para apoiar a gestão do conhecimento em paradas, recomenda-se elaborar relatório final que consolide informações para análise crítica dos desvios, lições aprendidas, futuras pesquisas e correção de desvios em paradas posteriores.",
          "trechos": [
            "E9a375624755afb26:0:696"
          ],
          "condicoes": [
            "aplicável ao contexto de paradas de manutenção",
            "voltado ao uso futuro pela organização"
          ],
          "limites": [
            "trata-se de recomendação bibliográfica, não exigência normativa",
            "o foco é parada de manutenção, não a operação contínua inteira do FPSO"
          ]
        },
        {
          "proposicao": "O conteúdo mínimo recomendado para o relatório final de parada inclui itens que sustentam interpretação de indicadores e comparação planejado versus realizado, como acidentes, escopo, prazos, custos, linha crítica e análise das causas dos desvios.",
          "trechos": [
            "E9a375624755afb26:696:1394"
          ],
          "condicoes": [
            "estrutura sugerida para consolidar dados da parada"
          ],
          "limites": [
            "o trecho lista conteúdos, mas não define padrão de qualidade dos dados nem método de validação",
            "não apresenta denominadores específicos para os indicadores mencionados"
          ]
        },
        {
          "proposicao": "Outra recomendação para o relatório final de parada é incluir metas da parada e um resumo comparativo entre metas e resultados nos KPIs, além de desempenho de contratadas, acompanhamento e controle dos trabalhos, recomendações e lições aprendidas, para formar base de dados para próximas paradas.",
          "trechos": [
            "E9a375624755afb26:1394:2092",
            "E9a375624755afb26:2092:2366"
          ],
          "condicoes": [
            "uso como base de dados para planejamento de paradas futuras"
          ],
          "limites": [
            "a fonte trata especificamente de paradas e não define metas universais de KPI para produção, segurança, ambiente ou equipes",
            "não há critérios explícitos de compatibilidade entre indicadores de diferentes empresas contratadas"
          ]
        }
      ]
    },
    {
      "id": "E0553c88d95ccb7bf",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na gestão de alarmes, a avaliação do desempenho considera a quantidade de alarmes por prioridade, e o trecho atribui à norma EEMUA um limite para alarmes classificados como alto, embora o número esteja suprimido.",
          "trechos": [
            "E0553c88d95ccb7bf:0:694"
          ],
          "condicoes": [
            "aplicável ao contexto de análise e classificação de alarmes",
            "referência a norma estrangeira citada no texto"
          ],
          "limites": [
            "o valor numérico do limite foi apagado e não pode ser reconstruído",
            "norma estrangeira citada em dissertação não deve ser tratada automaticamente como requisito brasileiro"
          ]
        },
        {
          "proposicao": "O agrupamento de alarmes por grupo e subgrupo é apresentado com duas finalidades: permitir visualização e reconhecimento por filtros e direcionar o operador para a tela específica do sistema com problema.",
          "trechos": [
            "E0553c88d95ccb7bf:0:694",
            "E0553c88d95ccb7bf:694:1386",
            "E0553c88d95ccb7bf:1386:2086"
          ],
          "condicoes": [
            "estruturação por afinidade dos sistemas",
            "em centros dedicados a mais de uma plataforma, o texto sugere agrupar primeiro por plataforma"
          ],
          "limites": [
            "o trecho trata de alarmes, não de um sistema geral de KPIs corporativos",
            "a estratégia descrita é contextual à dissertação"
          ]
        },
        {
          "proposicao": "A definição do nível de desempenho de um sistema de alarme exige adoção de metas para indicadores de desempenho e checagem por monitoramento dos resultados e comparação com a situação anterior ao plano de ação.",
          "trechos": [
            "E0553c88d95ccb7bf:1386:2086",
            "E0553c88d95ccb7bf:2086:2181"
          ],
          "condicoes": [
            "uso no acompanhamento de desempenho de sistemas de alarme",
            "comparação antes e depois da execução de plano de ação"
          ],
          "limites": [
            "o texto não explicita fórmulas dos KPIs nem define metas numéricas legíveis",
            "o termo KPIs aparece no contexto de alarmes, não necessariamente de produção, segurança ocupacional, ambiente e equipes em sentido amplo"
          ]
        }
      ]
    },
    {
      "id": "E85f5359eab31f388",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O relatório final de parada é recomendado como fonte de dados para futuras pesquisas e para correção de desvios em paradas futuras, apoiando a melhoria contínua do processo.",
          "trechos": [
            "E85f5359eab31f388:0:700"
          ],
          "condicoes": [
            "aplicação ao encerramento de paradas programadas de manutenção"
          ],
          "limites": [
            "é recomendação derivada de literatura citada, não norma",
            "escopo restrito a paradas, não cobrindo todo o ciclo operacional do FPSO"
          ]
        },
        {
          "proposicao": "Entre as informações mínimas recomendadas estão variáveis que estruturam indicadores e sua interpretação, como acidentes, escopo, prazos planejados e realizados, custos previstos e realizados, linha crítica, homens-hora e causas de desvios.",
          "trechos": [
            "E85f5359eab31f388:0:700",
            "E85f5359eab31f388:700:1400"
          ],
          "condicoes": [
            "uso para análise crítica de desempenho da parada"
          ],
          "limites": [
            "a fonte lista campos de informação, mas não define como calcular cada indicador",
            "não aborda explicitamente qualidade de dados além da necessidade de registro"
          ]
        },
        {
          "proposicao": "Outra recomendação de conteúdo do relatório é comparar metas e resultados da parada nos KPIs e incluir desempenho de empresas contratadas, segurança, qualidade, logística e comunicações.",
          "trechos": [
            "E85f5359eab31f388:700:1400",
            "E85f5359eab31f388:1400:2096"
          ],
          "condicoes": [
            "estrutura sugerida para relatório final de parada"
          ],
          "limites": [
            "não há definição de denominadores, metas quantitativas ou critérios de aceitação",
            "a presença de abordagem empírica anunciada na sequência não constitui resultado ainda apresentado nos trechos selecionados"
          ]
        }
      ]
    },
    {
      "id": "E3a62b13e285f3be8",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O regulamento define indicadores de desempenho como medidas quantitativas ou qualitativas, monitoradas e avaliadas periodicamente, que podem indicar o desempenho da organização.",
          "trechos": [
            "E3a62b13e285f3be8:0:693"
          ],
          "condicoes": [
            "definição normativa no contexto do SGSS"
          ],
          "limites": [
            "o trecho define o conceito, mas não fornece denominadores nem metas",
            "o contexto normativo é de sistemas submarinos, não de todos os subsistemas de um FPSO"
          ]
        },
        {
          "proposicao": "O regulamento distingue indicadores reativos, ligados ao tempo de reação a eventos não desejados e a medidas de desempenho passado, de indicadores pró-ativos, voltados à avaliação de condições que possam iniciar ou contribuir para incidentes operacionais.",
          "trechos": [
            "E3a62b13e285f3be8:0:693"
          ],
          "condicoes": [
            "aplicação à segurança operacional de sistemas submarinos"
          ],
          "limites": [
            "a definição não estabelece conjunto obrigatório específico de indicadores em produção, ambiente ou equipes",
            "não há método de integração desses indicadores com KPIs empresariais mais amplos"
          ]
        },
        {
          "proposicao": "A identificação de locais e trechos críticos depende de análise de riscos e sensibilidade operacional ou ambiental, o que condiciona a interpretação de desempenho e criticidade no sistema submarino.",
          "trechos": [
            "E3a62b13e285f3be8:0:693",
            "E3a62b13e285f3be8:2087:2338"
          ],
          "condicoes": [
            "uso em sistemas submarinos sob o regime do SGSS",
            "criticidade associada a análise de riscos ou localização em locais críticos"
          ],
          "limites": [
            "o trecho trata de criticidade e risco, não de metas de indicador",
            "não detalha critérios de qualidade de dados para a análise de riscos"
          ]
        }
      ]
    }
